UPDATE DOCUMENT_CATEGORIES
SET CONFIG_CATEGORY_ID = (
    SELECT ID FROM CONFIG_CATEGORIES
    WHERE CATEGORY_CODE = CASE DOCUMENT_CATEGORIES.CATEGORY_CODE
        WHEN 'ANNEX' THEN 'TEMPLATE_ANNEX'
        WHEN 'BILL' THEN 'TEMPLATE_BILL'
        WHEN 'MEMORANDUM' THEN 'TEMPLATE_MEMORANDUM'
        WHEN 'PROPOSAL' THEN 'TEMPLATE_PROPOSAL'
        WHEN 'STAT_DIGIT_FINANC_LEGIS' THEN 'TEMPLATE_STAT_DIGIT_FINANC_LEGIS'
    END
)
WHERE CATEGORY_CODE IN ('ANNEX', 'BILL', 'MEMORANDUM', 'PROPOSAL', 'STAT_DIGIT_FINANC_LEGIS');

